def write_vocabulary(path):
    data = zlib.decompress(base64.b85decode(PAYLOAD))
    if hashlib.sha256(data).hexdigest() != SHA256:
        raise ValueError('Frozen vocabulary checksum mismatch')
    lines = data.decode().splitlines()
    if lines[0] != 'gene_name' or len(set(lines[1:])) != 18533 or len(lines) != 18534:
        raise ValueError('Expected 18,533 unique official genes')
    path.parent.mkdir(parents=True, exist_ok=True)
    part = path.with_suffix('.tmp')
    part.write_bytes(data)
    part.replace(path)
